@startuml

class Employee {
  + name : string
  + ssn : int
}

class Driver extends Employee {}

class Planner extends Employee {}

class AdministrationEmployee extends Employee {
  + fieldOfActivity : string
  + username : string
  + password : string
}

class Customer {
  + name : string
  + billingAddress : string
}

class PartnerCompany {
  + name : string
  + address : string
}

class Vehicle {
  + licensePlateNumber : string
  + mileage : int
}

class RefrigeratedTruck extends Vehicle {}

class SmallVan extends Vehicle {}

class LoadingPlatform extends Vehicle {}

class BoxTruck extends Vehicle {}

class RepairShop {
  + name : string
  + address : string
}

class Repair {
  + duration : string
  + cost : float
}

class Order {
  + packageSize : string
  + pickUpAddress : string
  + deliveryAddress : string
  + comment : string
  + startTime : datetime
  + finishTime : datetime
}

class Assignment {
}

Employee "1" -- "*" Repair : takes vehicle to
Repair "*" -- "1" RepairShop : occurs at
Repair "*" -- "1" Vehicle : involves

Order "*" -- "1" Customer : placed by
Order "*" -- "1" PartnerCompany : placed by
Order "*" -- "1" Customer : client

Order "*" -- "1" Driver : assigned to
Order "*" -- "1" Driver : completed by
Order "*" -- "1" Vehicle : uses
Order "*" -- "1" Planner : assigned by

Assignment "*" -- "1" Order : links
Assignment "*" -- "1" Driver : involves
Assignment "*" -- "1" Vehicle : involves

@enduml

